cd /tmp && python3 -I - <<'PY'
import json
sets={}
for step in [1,50,100]:
    rows=[json.loads(l) for l in open(f'/workspace/results/run100/rollouts/{step}.jsonl')]
    prompts=set(r['input'] for r in rows)
    sets[step]=prompts
    print(step,len(prompts))
for a in sets:
    for b in sets:
        if a<b: print(a,b,'overlap',len(sets[a]&sets[b]))
# val prompts
val=set(json.loads(l)['input'] for l in open('/workspace/results/run100/val_generations/0.jsonl'))
print('val prompts',len(val))
for s in sets: print('val vs',s,len(val&sets[s]))
PY

