import json, re, pyarrow.parquet as pq, statistics
t=pq.read_table('/workspace/data/gsm8k/test.parquet').to_pydict()
gold={}
for i in range(len(t['data_source'])):
    q=t['extra_info'][i]['question']
    gold[q]=t['extra_info'][i]['answer']
rows0=[json.loads(l) for l in open('/workspace/results/run100/val_generations/0.jsonl')]
rows1=[json.loads(l) for l in open('/workspace/results/run100/val_generations/100.jsonl')]
def lastnum(o):
    ns=re.findall(r'(-?[0-9][0-9,]*(?:\.[0-9]+)?)', o.replace('$','').replace(',',''))
    return ns[-1] if ns else None
# match by question text: prompt content before the instruction
import difflib
def qtext(inp):
    # strip chat template: last 'user\n' block, remove instruction suffix
    s=inp.split('user\n')[-1]
    s=s.split(' Let\'s think step by step')[0]
    return s.strip()
buckets={'lost':[], 'gained':[], 'stay_right':[], 'stay_wrong':[]}
nmatch=0
for a,b in zip(rows0,rows1):
    q=qtext(a['input'])
    if q not in gold:
        # try fuzzy
        cand=difflib.get_close_matches(q, gold.keys(), n=1, cutoff=0.95)
        if not cand: continue
        q=cand[0]
    nmatch+=1
    L=len(gold[q])
    c0 = lastnum(a['output'])==str(a['gts']).strip()
    c1 = b.get('score',0)>=1
    if c0 and not c1: buckets['lost'].append(L)
    elif c1 and not c0: buckets['gained'].append(L)
    elif c0 and c1: buckets['stay_right'].append(L)
    else: buckets['stay_wrong'].append(L)
print('matched',nmatch)
for k,v in buckets.items():
    print(k, len(v), 'mean gold len %.0f median %d'%(statistics.mean(v), statistics.median(v)) if v else '')
EOF

