python3 -I - /workspace/models/Qwen2.5-0.5B-Instruct /workspace/results/run100 <<'PY'
import json,sys,os,re
from transformers import AutoTokenizer
tok=AutoTokenizer.from_pretrained(sys.argv[1], trust_remote_code=False)
root=sys.argv[2]
def load(p): return [json.loads(l) for l in open(p) if l.strip()]
def maxrun(t):
    best=0
    for m in re.finditer(r'(.)\1*', t): best=max(best,len(m.group(0)))
    return best
def tailrun(t):
    m=re.search(r'(.)\1*$', t); return len(m.group(0)) if m else 0
def na(t): return sum(1 for c in t if ord(c)>127)
print('ROLLOUTS')
for step in (1,50,100):
    rows=load(os.path.join(root,'rollouts',f'{step}.jsonl'))
    at=set(); 
    for r in rows:
        if len(tok(r['output'],add_special_tokens=False)['input_ids'])>=510: at.add(id(r))
    g={id(r) for r in rows if na(r['output'])>=10}
    print(f"step {step}: n={len(rows)} at510={len(at)} gib(nonascii>=10)={len(g)} overlap={len(at&g)} gib_not_capped={len(g-at)} capped_not_gib={len(at-g)}")
    for thr in (20,40,60,100):
        c=[r for r in rows if maxrun(r['output'])>=thr]
        print(f"   maxrun>={thr}: {len(c)}", end='')
    print()
print('VAL')
for step in (0,50,100):
    rows=load(os.path.join(root,'val_generations',f'{step}.jsonl'))
    sc=lambda rs: sum(float(x['score']) for x in rs)/max(len(rs),1)
    for thr in (20,40,60,100):
        c=[r for r in rows if maxrun(r['output'])>=thr]
        print(f"   maxrun>={thr}: {len(c)} ({len(c)/len(rows):.1%}) score={sc(c):.3f}", end='')
    print()
    for thr in (40,60,100):
        c=[r for r in rows if tailrun(r['output'])>=thr]
        print(f"   tail>={thr}: {len(c)} ({len(c)/len(rows):.1%}) score={sc(c):.3f}", end='')
    print()
PY

